// CSD_RATIONALE_BEGIN
// Root-cause analysis relative to best attempt (24: 34.7% accuracy, 79.6% syntax)
// and most-recent attempt (26: 18.4% accuracy, 77.6% syntax):
//
// Attempt 26 regressed badly because its hand-written loop introduced a double-cost
// bug (CloseSpanIfComplete + ConstrainedStep both within one `steps` increment while
// the span closed or not) and its mode detection was noisy.
//
// The best-known structure is GenerateWithPrefixAndManagedSpan (attempt 24).
// Two failure clusters dominate:
//
// mode_A (15 wrong): tiny_span_dominant. The model writes <<n>>, <<k2>> etc. as
//   variable references during reasoning. These become 1-token constrained spans
//   (single variable name is a complete parse). The last tiny span is extracted as
//   the answer. Fix: guidance that FORBIDS using << >> during reasoning AND
//   mandates int() wrapping. With int(), the parser won't close the span after
//   just `n`; it must see `int(n …)` which forces a longer expression before
//   completeness is reached.
//
// mode_C (5 no-span): model reasons to EOS without ever writing <<.
//   Fix: GenerateWithPrefixAndManagedSpan forces OpenConstrainedSpan at
//   prefixBudget when the span was never entered.
//
// Unterminated spans (7 + mode_F 2): << opened with too little budget left.
//   Fix: higher prefixBudget (85% = 765 steps), leaving 135 steps guaranteed
//   for CloseSpanWithinBudget inside the helper.
//
// Accuracy (18.4%→target 44.9%): revert to the best-known base structure and
//   sharpen guidance to steer the model toward complete, correct symbolic
//   formulas rather than partial variable references.
//
// Parameters:
//   prefixBudget = 85% of maxSteps (765/900)
//   boostAmount  = 8.0 (unchanged from best result)
//   narrowThreshold = 6 (unchanged from best result)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Initialization: copied from precondition-valid inputs (no change in the
//   maxSteps==0 branch). In the else branch, GenerateWithPrefixAndManagedSpan
//   postcondition directly guarantees both:
//     !insideConstrainedOut ==> currentConstrainedOut == []
//     insideConstrainedOut  ==> parser.IsValidPrefix(currentConstrainedOut)
//   No code runs after the helper call that could alter these out-parameters,
//   so the invariant holds on return.
//
// progress: |generated| <= |generatedPrefix| + maxSteps, cost <= maxSteps
//   maxSteps==0 branch: generated unchanged, cost=0 ≤ 0. Liveness: maxSteps==0
//   satisfies the disjunct directly.
//   else branch: GenerateWithPrefixAndManagedSpan postcondition guarantees
//   |generated| <= |generatedPrefix| + maxSteps. We set cost := maxSteps,
//   so cost <= maxSteps. When maxSteps > 0, cost = maxSteps > 0 satisfies
//   the liveness postcondition immediately.
//   Each token-step consumed by the helper—whether the token is appended to
//   visible output, used as an EOS/rejected suffix, or spent on the forced
//   delimiter—is counted against the single maxSteps budget, so the sum of
//   all consumed steps is ≤ maxSteps and visible output growth is bounded by
//   the same budget.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step using only plain text. At the VERY END of your solution write exactly ONE final answer as <<int(expr)>>. ALWAYS wrap in int(). Use bare variable names: write n not {n}, mult not {mult}, price not {price}. Allowed inside << >>: variable names, integers, +, -, *, /, //, %, (, ), int(). Example final line: The answer is <<int(n * price - (n * price * discount // 100))>>. Do NOT place << >> around intermediate steps or variable references — ONLY the single final symbolic answer gets << >>. No LaTeX, no {braces}, no ** operator.");

  var prefixBudget: nat := (maxSteps * 85) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 8.0, 6, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

